  const brick = singleBrick(100, 100)[0];
  const bricks = [brick];
  const ball = { x: 130, y: 96, r: 7, vx: 0, vy: 100, px: 130, py: 90 };

  resolveBrickBounce(ball, bricks);
  assert.equal(collides(ball, brick), false, 'after push-out the ball no longer overlaps');
