  // Two vertically stacked bricks with an 8 px gap; the ball straddles the seam.
  const top = { x: 100, y: 100, w: 72, h: 20, alive: true };   // y 100..120
  const bottom = { x: 100, y: 128, w: 72, h: 20, alive: true }; // y 128..148
  const bricks = [bottom, top];
